/**
 * @file     startup_logo.c
 * @brief    Startup picture shown before the transcript takes over the LCD.
 * @details  The pixels live in images/startup_logo_image.h (generated by
 *           tools/image_to_rgb565.py) and stay in XIP flash; they are copied
 *           into the framebuffer once.
 * @author   Nikita Prismakov
 *
 * SPDX-FileCopyrightText: 2026 Nikita Prismakov
 * SPDX-License-Identifier: Apache-2.0
 */

/*******************************************************************************/
/*                                   INCLUDES                                  */
/*******************************************************************************/

#include "startup_logo.h"

#include "images/startup_logo_image.h"
#include "logger.h"
#include "mw_lcd.h"

/*******************************************************************************/
/*                              PRIVATE VARIABLES                              */
/*******************************************************************************/

/** @brief The startup logo as the LCD middleware sees it. */
static const mw_lcd_image_t startup_logo_image = {
  .width = STARTUP_LOGO_IMAGE_WIDTH,
  .height = STARTUP_LOGO_IMAGE_HEIGHT,
  .pixels = startup_logo_image_pixels,
};

/*******************************************************************************/
/*                               PUBLIC FUNCTIONS                              */
/*******************************************************************************/

uint32_t startup_logo_show(void)
{
  /* Black fills whatever the picture does not cover on another panel size. */
  mw_lcd_clear(MW_LCD_COLOR_BLACK);
  if (mw_lcd_draw_image_centered(&startup_logo_image) != MW_LCD_OK)
  {
    LOG_ERROR("Startup logo draw failed");
    return 1U;
  }
  if (mw_lcd_present() != MW_LCD_OK)
  {
    LOG_ERROR("Startup logo presentation failed");
    return 1U;
  }
  return 0U;
}
